class Tokenizer{static tokenize(b){if(!b)return[];b=b.toLowerCase().replace(/[^\w\s]/g,"");var d=b.split(/\s+/).filter(c=>c.length>0),f=[];for(let c=0;c<b.length-1;c++){let g=b.substring(c,c+2);/\s/.test(g)||f.push(g)}return d.concat(f)}}typeof globalThis!=="undefined"&&(globalThis.Tokenizer=Tokenizer);typeof module!=="undefined"&&module.exports&&(module.exports=Tokenizer);class VectorScorer{static calculateCosineSimilarity(b,d){var f=0;Object.keys(b).forEach(c=>{d[c]&&(f+=b[c]*d[c])});return f}}typeof globalThis!=="undefined"&&(globalThis.VectorScorer=VectorScorer);typeof module!=="undefined"&&module.exports&&(module.exports=VectorScorer);class CustomSearchEngine{constructor(){this.docs=[];this.idf={};this.vectors=[];this.isLoaded=!1}async loadIndex(b="search_index.json"){try{let d=await (await fetch(b)).json();this.docs=d.docs;this.idf=d.idf;this.vectors=d.vectors;return this.isLoaded=!0}catch(d){return console.error("\u274c \u30a4\u30f3\u30c7\u30c3\u30af\u30b9\u30ed\u30fc\u30c9\u5931\u6557:",d),!1}}tokenize(b){return Tokenizer.tokenize(b)}search(b,d=10){if(!this.isLoaded||!b.trim())return[];var f=this.tokenize(b);if(f.length===0)return[];
var c={};f.forEach(a=>{c[a]=(c[a]||0)+1});var g={},h=0;Object.keys(c).forEach(a=>{if(Object.prototype.hasOwnProperty.call(this.idf,a)){let e=c[a]/f.length*(this.idf[a]||1);g[a]=e;h+=e*e}});var n=h>0?Math.sqrt(h):1,l={};Object.keys(g).forEach(a=>{l[a]=g[a]/n});var k=[],m=b.toLowerCase();this.docs.forEach((a,e)=>{e=VectorScorer.calculateCosineSimilarity(l,this.vectors[e]||{});var p=a.name.toLowerCase(),q=a.summary.toLowerCase();p.includes(m)?e+=2:q.includes(m)&&(e+=.5);e>.05&&k.push({doc:a,score:e})});
k.sort((a,e)=>e.score-a.score);return k.slice(0,d).map(a=>({...a.doc,score:a.score.toFixed(4)}))}}typeof window!=="undefined"&&(window.CustomSearchEngine=CustomSearchEngine);typeof module!=="undefined"&&module.exports&&(module.exports=CustomSearchEngine);
